INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_029_M4_S4', 'load balancing', '4', 'load balancing: Distribution of computational, network, or service workload across available resources to improve utilization, throughput, latency, or availability. In Data Center Networking, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M4_S5', 'network virtualization', '5', 'network virtualization: Creating logical networks, segments, or network functions independently of fixed physical network connections. In Data Center Networking, the focus is on the analysis, design, implementation, interpretation, or evaluation of network virtualization within Data Center Operations and Infrastructure, particularly where the Data Center Networking module establishes its technical context.', 'SSD_COURSE_029_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M4_S6', 'high-availability design', '6', 'high-availability design: Designing infrastructure to maintain service availability despite component failures through redundancy, fault isolation, failover, and maintainability. In Data Center Networking, the focus is on the analysis, design, implementation, interpretation, or evaluation of high-availability design within Data Center Operations and Infrastructure, particularly where the Data Center Networking module establishes its technical context.', 'SSD_COURSE_029_M4_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M5_S1', 'Uninterruptible Power Supply (UPS)', '1', 'UPS: Uninterruptible power supply systems that provide conditioned electrical power and temporary ride-through or backup power to loads when the normal supply is disturbed or unavailable. In Power Systems and Energy Management, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M5_S2', 'generators', '2', 'generators: Machines that convert mechanical energy into electrical energy through electromagnetic induction and supply electrical loads or power-system networks. In Power Systems and Energy Management, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M5_S3', 'power distribution', '3', 'power distribution: Arrangement and operation of electrical equipment and conductors used to distribute power from sources or upstream systems to loads at the required voltage and reliability level. In Power Systems and Energy Management, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M5_S4', 'Power Usage Effectiveness (PUE)', '4', 'PUE: Power Usage Effectiveness, the ratio of total data-center facility energy to energy delivered to IT equipment. In Power Systems and Energy Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of PUE within Data Center Operations and Infrastructure, particularly where the Power Systems and Energy Management module establishes its technical context.', 'SSD_COURSE_029_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M5_S5', 'demand management', '5', 'demand management: Managing computing or facility demand to control capacity, power use, cost, or peak loads. In Power Systems and Energy Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of demand management within Data Center Operations and Infrastructure, particularly where the Power Systems and Energy Management module establishes its technical context.', 'SSD_COURSE_029_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M5_S6', 'power quality', '6', 'power quality refers to the characteristics of electrical power, including voltage variation, frequency deviation, harmonics, transients, and interruptions, that affect equipment operation. In Power Systems and Energy Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of power quality within Data Center Operations and Infrastructure, particularly where the Power Systems and Energy Management module establishes its technical context.', 'SSD_COURSE_029_M5_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M6_S1', 'Computer Room Air Conditioner / Computer Room Air Handler (CRAC/CRAH)', '1', 'CRAC/CRAH: Computer-room air-conditioning or air-handler systems used to remove heat and condition data-center air. In Cooling and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of CRAC/CRAH within Data Center Operations and Infrastructure, particularly where the Cooling and Thermal Management module establishes its technical context.', 'SSD_COURSE_029_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M6_S2', 'chilled water', '2', 'chilled water: Water circulated through cooling equipment to remove heat from data-center air or IT equipment. In Cooling and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of chilled water within Data Center Operations and Infrastructure, particularly where the Cooling and Thermal Management module establishes its technical context.', 'SSD_COURSE_029_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M6_S3', 'airflow management', '3', 'airflow management: Controlling supply, return, pressure, and equipment layout to deliver cooling air where heat is generated. In Cooling and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of airflow management within Data Center Operations and Infrastructure, particularly where the Cooling and Thermal Management module establishes its technical context.', 'SSD_COURSE_029_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M6_S4', 'heat rejection', '4', 'heat rejection: Transfer of heat from a data-centre cooling system to the surrounding environment through air, water, or other heat-rejection systems. In Cooling and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat rejection within Data Center Operations and Infrastructure, particularly where the Cooling and Thermal Management module establishes its technical context.', 'SSD_COURSE_029_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M6_S5', 'thermal monitoring', '5', 'thermal monitoring: Measuring temperatures and thermal conditions to detect hotspots, cooling problems, and capacity limits. In Cooling and Thermal Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of thermal monitoring within Data Center Operations and Infrastructure, particularly where the Cooling and Thermal Management module establishes its technical context.', 'SSD_COURSE_029_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M7_S1', 'hypervisors', '1', 'hypervisors: Software or firmware layers that create and manage virtual machines by controlling access to physical computing resources. In Virtualization and Infrastructure Management, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M7_S2', 'containers', '2', 'containers: OS-level application isolation units that package application code and dependencies while sharing a host operating-system kernel. In Virtualization and Infrastructure Management, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M7_S3', 'resource pools', '3', 'resource pools: Groups of shared compute, memory, storage, or network resources allocated to workloads as needed. In Virtualization and Infrastructure Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of resource pools within Data Center Operations and Infrastructure, particularly where the Virtualization and Infrastructure Management module establishes its technical context.', 'SSD_COURSE_029_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M7_S4', 'capacity management', '4', 'capacity management: Planning and tracking available and required power, cooling, space, compute, storage, and network capacity. In Virtualization and Infrastructure Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of capacity management within Data Center Operations and Infrastructure, particularly where the Virtualization and Infrastructure Management module establishes its technical context.', 'SSD_COURSE_029_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M7_S5', 'infrastructure automation', '5', 'infrastructure automation: Automating provisioning, configuration, monitoring, and operational changes across data-center infrastructure. In Virtualization and Infrastructure Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of infrastructure automation within Data Center Operations and Infrastructure, particularly where the Virtualization and Infrastructure Management module establishes its technical context.', 'SSD_COURSE_029_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M8_S1', 'Data Center Infrastructure Management (DCIM)', '1', 'DCIM: Data Center Infrastructure Management tools and practices for monitoring and managing facility and IT infrastructure. In Monitoring, Reliability and Emerging Technologies, the focus is on the analysis, design, implementation, interpretation, or evaluation of DCIM within Data Center Operations and Infrastructure, particularly where the Monitoring, Reliability and Emerging Technologies module establishes its technical context.', 'SSD_COURSE_029_M8_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M8_S2', 'telemetry', '2', 'telemetry: Operational measurements collected from infrastructure and equipment for monitoring, analysis, and control. In Monitoring, Reliability and Emerging Technologies, the focus is on the analysis, design, implementation, interpretation, or evaluation of telemetry within Data Center Operations and Infrastructure, particularly where the Monitoring, Reliability and Emerging Technologies module establishes its technical context.', 'SSD_COURSE_029_M8_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M8_S3', 'incident management', '3', 'incident management: Processes for detecting, responding to, resolving, and learning from data-center service incidents. In Monitoring, Reliability and Emerging Technologies, the focus is on the analysis, design, implementation, interpretation, or evaluation of incident management within Data Center Operations and Infrastructure, particularly where the Monitoring, Reliability and Emerging Technologies module establishes its technical context.', 'SSD_COURSE_029_M8_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M8_S4', 'redundancy', '4', 'redundancy: Provision of duplicate or alternative components, paths, or resources so that loss or failure of one element does not necessarily cause loss of required service. In Monitoring, Reliability and Emerging Technologies, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M8_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M8_S5', 'liquid cooling', '5', 'liquid cooling: Cooling methods that use liquid to remove heat from high-density IT equipment more effectively than air alone. In Monitoring, Reliability and Emerging Technologies, the focus is on the analysis, design, implementation, interpretation, or evaluation of liquid cooling within Data Center Operations and Infrastructure, particularly where the Monitoring, Reliability and Emerging Technologies module establishes its technical context.', 'SSD_COURSE_029_M8_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M8_S6', 'edge computing', '6', 'edge computing: Placing computing and data-processing resources close to data sources or users to reduce latency or network load. In Monitoring, Reliability and Emerging Technologies, the focus is on the analysis, design, implementation, interpretation, or evaluation of edge computing within Data Center Operations and Infrastructure, particularly where the Monitoring, Reliability and Emerging Technologies module establishes its technical context.', 'SSD_COURSE_029_M8_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M1_S1', 'cement chemistry', '1', 'cement chemistry: Chemical composition and reactions of cement phases that control hydration, setting, strength development, and durability. In Cement and Supplementary Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of cement chemistry within Concrete Technology, particularly where the Cement and Supplementary Materials module establishes its technical context.', 'SSD_COURSE_030_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M1_S2', 'hydration', '2', 'hydration: Chemical reactions between cement and water that form hydration products and cause concrete to set and harden. In Cement and Supplementary Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of hydration within Concrete Technology, particularly where the Cement and Supplementary Materials module establishes its technical context.', 'SSD_COURSE_030_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M1_S3', 'supplementary cementitious materials', '3', 'supplementary cementitious materials: Reactive or partly reactive mineral materials used with cement to modify concrete properties and reduce the proportion of Portland cement, such as fly ash, slag, or silica fume. In Cement and Supplementary Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of supplementary cementitious materials within Concrete Technology, particularly where the Cement and Supplementary Materials module establishes its technical context.', 'SSD_COURSE_030_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M1_S4', 'blended cements', '4', 'blended cements: Cements containing supplementary cementitious materials or other constituents that modify performance and durability. In Cement and Supplementary Materials, the focus is on the analysis, design, implementation, interpretation, or evaluation of blended cements within Concrete Technology, particularly where the Cement and Supplementary Materials module establishes its technical context.', 'SSD_COURSE_030_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M2_S1', 'aggregate grading', '1', 'aggregate grading refers to the distribution of aggregate particle sizes used to control packing, workability, voids, and concrete proportions. In Aggregates and Mix Constituents, the focus is on the analysis, design, implementation, interpretation, or evaluation of aggregate grading within Concrete Technology, particularly where the Aggregates and Mix Constituents module establishes its technical context.', 'SSD_COURSE_030_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M2_S2', 'shape and texture', '2', 'shape and texture: Aggregate particle shape and surface texture that influence packing, workability, paste demand, and bond. In Aggregates and Mix Constituents, the focus is on the analysis, design, implementation, interpretation, or evaluation of shape and texture within Concrete Technology, particularly where the Aggregates and Mix Constituents module establishes its technical context.', 'SSD_COURSE_030_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M2_S3', 'moisture', '3', 'moisture: Water present in aggregates, which affects the effective mixing water and concrete mix proportions. In Aggregates and Mix Constituents, the focus is on the analysis, design, implementation, interpretation, or evaluation of moisture within Concrete Technology, particularly where the Aggregates and Mix Constituents module establishes its technical context.', 'SSD_COURSE_030_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M2_S4', 'admixtures', '4', 'admixtures: Materials added in small quantities to concrete to modify properties such as workability, setting, strength, or durability. In Aggregates and Mix Constituents, the focus is on the analysis, design, implementation, interpretation, or evaluation of admixtures within Concrete Technology, particularly where the Aggregates and Mix Constituents module establishes its technical context.', 'SSD_COURSE_030_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M2_S5', 'mixing water', '5', 'mixing water: Water added to a concrete mixture to enable hydration and provide the required workability. In Aggregates and Mix Constituents, the focus is on the analysis, design, implementation, interpretation, or evaluation of mixing water within Concrete Technology, particularly where the Aggregates and Mix Constituents module establishes its technical context.', 'SSD_COURSE_030_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M3_S1', 'water-cement ratio', '1', 'water-cement ratio refers to the mass ratio of mixing water to cement, strongly affecting concrete strength, permeability, and durability. In Concrete Mix Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of water-cement ratio within Concrete Technology, particularly where the Concrete Mix Design module establishes its technical context.', 'SSD_COURSE_030_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M3_S2', 'absolute volume method', '2', 'absolute volume method refers to a mix-design method that proportions concrete constituents by their absolute volumes so the total volume equals the batch volume. In Concrete Mix Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of absolute volume method within Concrete Technology, particularly where the Concrete Mix Design module establishes its technical context.', 'SSD_COURSE_030_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M3_S3', 'target strength', '3', 'target strength refers to the specified average strength used in mix design to provide the required probability of achieving characteristic strength. In Concrete Mix Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of target strength within Concrete Technology, particularly where the Concrete Mix Design module establishes its technical context.', 'SSD_COURSE_030_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M3_S4', 'workability', '4', 'workability refers to the ease with which fresh concrete can be mixed, transported, placed, compacted, and finished while maintaining the required uniformity and stability. In Concrete Mix Design, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_030_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M3_S5', 'proportioning', '5', 'proportioning: Determining the quantities of cementitious material, aggregate, water, and admixtures required for a concrete mix. In Concrete Mix Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of proportioning within Concrete Technology, particularly where the Concrete Mix Design module establishes its technical context.', 'SSD_COURSE_030_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M4_S1', 'workability', '1', 'workability refers to the ease with which fresh concrete can be mixed, transported, placed, compacted, and finished while maintaining the required uniformity and stability. In Fresh Concrete, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_030_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M4_S2', 'segregation', '2', 'segregation: Separation of coarse aggregate from mortar or paste during handling, placing, or compaction of concrete. In Fresh Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of segregation within Concrete Technology, particularly where the Fresh Concrete module establishes its technical context.', 'SSD_COURSE_030_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M4_S3', 'bleeding', '3', 'bleeding: Upward movement of water to the concrete surface as solid particles settle after placement. In Fresh Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of bleeding within Concrete Technology, particularly where the Fresh Concrete module establishes its technical context.', 'SSD_COURSE_030_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M4_S4', 'setting', '4', 'setting refers to the transition of cement paste from a fluid state to a rigid state during hydration. In Fresh Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of setting within Concrete Technology, particularly where the Fresh Concrete module establishes its technical context.', 'SSD_COURSE_030_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M4_S5', 'placing', '5', 'placing: Depositing fresh concrete into its required position while maintaining uniformity and avoiding defects. In Fresh Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of placing within Concrete Technology, particularly where the Fresh Concrete module establishes its technical context.', 'SSD_COURSE_030_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M4_S6', 'compaction', '6', 'compaction: Removing entrapped air from fresh concrete to achieve adequate density and contact with reinforcement or formwork. In Fresh Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of compaction within Concrete Technology, particularly where the Fresh Concrete module establishes its technical context.', 'SSD_COURSE_030_M4_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M5_S1', 'strength', '1', 'strength refers to the capacity of hardened concrete to resist specified mechanical actions such as compression, tension, or flexure. In Hardened Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of strength within Concrete Technology, particularly where the Hardened Concrete module establishes its technical context.', 'SSD_COURSE_030_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M5_S2', 'modulus', '2', 'modulus refers to a measure of concrete stiffness relating stress to strain within the applicable range of behaviour. In Hardened Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of modulus within Concrete Technology, particularly where the Hardened Concrete module establishes its technical context.', 'SSD_COURSE_030_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M5_S3', 'shrinkage', '3', 'shrinkage: Volume reduction in concrete caused by moisture loss, chemical reactions, or other mechanisms independent of external loading. In Hardened Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of shrinkage within Concrete Technology, particularly where the Hardened Concrete module establishes its technical context.', 'SSD_COURSE_030_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M5_S4', 'creep', '4', 'creep: Time-dependent deformation of concrete under sustained stress. In Hardened Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of creep within Concrete Technology, particularly where the Hardened Concrete module establishes its technical context.', 'SSD_COURSE_030_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_030_M5_S5', 'permeability', '5', 'permeability refers to the ability of concrete to allow fluids or gases to pass through its pore structure. In Hardened Concrete, the focus is on the analysis, design, implementation, interpretation, or evaluation of permeability within Concrete Technology, particularly where the Hardened Concrete module establishes its technical context.', 'SSD_COURSE_030_M5_S5', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;